// GPT-Live client delegation: media remains open while DeepSeek works.
export class LiveVoice {
 constructor({api,status,message,onJobs,context}){Object.assign(this,{api,status,message,onJobs,context});this.generation=0;this.transcripts=[];this.seen=new Set();this.pending=new Set();}
 send(type,content,delegation_id=null){if(this.ready&&this.channel?.readyState==='open')this.channel.send(JSON.stringify({type,event_id:crypto.randomUUID(),content,delegation_id}));}
 async connect(){if(this.pc||this.connecting)return;this.connecting=true;const gen=++this.generation;this.status('GPT-Live正在连接…');try{const config=await this.api('/api/live-voice/status');if(!config.configured)throw Error('GPT-Live未配置：请在本机填写 OpenAI API Key');const stream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true}});if(gen!==this.generation){stream.getTracks().forEach(t=>t.stop());return}this.stream=stream;const pc=this.pc=new RTCPeerConnection();this.audio=new Audio();this.audio.autoplay=true;pc.ontrack=e=>{if(gen===this.generation){this.audio.srcObject=e.streams[0];this.audio.play().catch(()=>this.status('请点击页面允许音频播放'))}};for(const track of stream.getTracks())pc.addTrack(track,stream);const dc=this.channel=pc.createDataChannel('oai-events');dc.onmessage=e=>{if(gen!==this.generation)return;try{this.event(JSON.parse(e.data),gen)}catch{this.status('语音事件无法解析')}};pc.onconnectionstatechange=()=>{if(gen===this.generation&&['failed','disconnected'].includes(pc.connectionState)){this.stop();this.status('语音连接中断，可重新接通；后台研究继续')}};await pc.setLocalDescription(await pc.createOffer());const response=await this.api('/api/live-voice/session',{sdp:pc.localDescription.sdp});if(gen!==this.generation)return;this.sessionId=response.session.id;await pc.setRemoteDescription({type:'answer',sdp:response.transport.sdp});this.timeout=setTimeout(()=>{if(gen===this.generation&&!this.ready){this.stop();this.status('未收到语音启动确认，请重试')}},20000);}catch(e){if(gen===this.generation){this.stop();this.status(e.message)}}}
 event(e,gen){if(this.closing&&e.type!=='session.closed')return;if(e.event_id){if(this.seen.has(e.event_id))return;this.seen.add(e.event_id)}if(e.type==='session.started'){clearTimeout(this.timeout);this.connecting=false;this.ready=true;this.status('GPT-Live全双工已连接 · DeepSeek后台研究');this.limit=setTimeout(()=>this.stop(),900000);return}if(e.type==='session.closed'){this.cleanup();this.status('语音已结束 · 后台研究继续');return}if(e.type==='error'){this.status('语音服务报告错误，请重新接通');return}if(e.type==='session.input_transcript.delta'||e.type==='session.output_transcript.delta'){const role=e.type.includes('.input_')?'user':'assistant';if(typeof e.delta!=='string')return;this.transcripts.push({role,content:e.delta,start:e.start_ms,end:e.end_ms});this.transcripts=this.transcripts.slice(-800);this.message(role,e.delta);return}if(e.type==='session.delegation.created'&&e.delegation?.target==='client')void this.delegate(e,gen);}
 async delegate(e,gen){const id=e.delegation.id;if(this.pending.has(id))return;this.pending.add(id);const messages=[];for(const item of this.transcripts.filter(t=>!Number.isFinite(e.offset_ms)||t.start<=e.offset_ms)){const last=messages.at(-1);if(last?.role===item.role&&last.content.length+item.content.length<5500)last.content+=item.content;else messages.push({role:item.role,content:item.content.slice(-5500)})}if(!messages.some(m=>m.role==='user')){this.send('session.commentary.append','我还没有收到完整问题，请再说一下需要研究的品种。',id);return}messages.push({role:'user',content:'当前工作台选中的实际合约：'+(this.context?.()||'未选择')+'。请根据以上语音上下文处理最新请求，结果用简短中文，深度研究应在后台启动。'});this.send('session.thinking.append','已交给DeepSeek查询真实数据。',id);try{const result=await this.api('/api/live-voice/delegate',{sessionId:this.sessionId,delegationId:id,messages:messages.slice(-24)});if(gen!==this.generation)return;this.onJobs?.(result.jobs||[]);this.send('session.commentary.append',result.text.slice(0,380),id)}catch{if(gen===this.generation)this.send('session.commentary.append','后台查询未完成，请在研究面板核对任务状态。',id)}}
 mute(value){this.stream?.getAudioTracks().forEach(t=>t.enabled=!value)}
 interrupt(){if(this.audio)this.audio.muted=true;this.send('session.instructions.append','立即停止当前播报，继续聆听。不要取消后台研究。');clearTimeout(this.unmute);this.unmute=setTimeout(()=>{if(this.audio)this.audio.muted=false},1500)}
 stop(){this.closing=true;clearTimeout(this.timeout);clearTimeout(this.limit);if(this.ready&&this.channel?.readyState==='open'){this.channel.send(JSON.stringify({type:'session.close'}));this.ready=false;this.status('正在结束语音 · 后台研究继续');this.stream?.getTracks().forEach(t=>t.stop());this.closeTimer=setTimeout(()=>this.cleanup(),3000)}else this.cleanup()}
 cleanup(){this.generation++;clearTimeout(this.timeout);clearTimeout(this.limit);clearTimeout(this.closeTimer);clearTimeout(this.unmute);this.ready=false;this.channel?.close();this.pc?.close();this.stream?.getTracks().forEach(t=>t.stop());if(this.audio){this.audio.pause();this.audio.srcObject=null}this.closing=false;this.connecting=false;this.pc=null;this.channel=null;this.stream=null;this.audio=null;this.transcripts=[];this.seen.clear();this.pending.clear();}
}
